// === PREPARACIÓN DE DATOS PARA AI AGENT ===
const entrada = $input.first().json;
const historial = entrada.historial_clinico || {};

// Extraer datos críticos
const pacienteId = entrada.paciente_id;
const datosBasicos = historial.datos_basicos || {};
const datosClinicos = historial.datos_clinicos || {};
const triaje = historial.triaje_inicial || {};
const diagnosticos = historial.diagnosticos || {};
const predicciones = historial.predicciones_fastapi || {};

console.log('=== PREPARANDO PARA AI AGENT ===');
console.log('Paciente ID:', pacienteId);
console.log('Edad:', datosBasicos.edad);
console.log('Diagnóstico:', diagnosticos.codigo_cie10);

// Construir contexto médico estructurado para AI Agent
const contextoMedico = {
  paciente: {
    id: pacienteId,
    edad: datosBasicos.edad || null,
    genero: datosBasicos.genero || null
  },
  vitales: {
    presion_sistolica: datosClinicos.presion_arterial_sistolica || null,
    presion_diastolica: datosClinicos.presion_arterial_diastolica || null,
    colesterol_total: datosClinicos.colesterol_total || null,
    hdl: datosClinicos.hdl || null,
    frecuencia_cardiaca: datosClinicos.frecuencia_cardiaca_max || null
  },
  factores_riesgo: {
    tabaquismo: triaje.factores_riesgo?.tabaquismo || false,
    diabetes: triaje.factores_riesgo?.diabetes || false,
    hipertension: triaje.factores_riesgo?.hipertension || false,
    antecedentes_cardiacos: triaje.factores_riesgo?.antecedentes_cardiacos || false,
    actividad_fisica: triaje.factores_riesgo?.actividad_fisica || false
  },
  sintomas_actuales: {
    dolor_pecho: triaje.sintomas?.dolor_pecho || false,
    dolor_irradiado: triaje.sintomas?.dolor_irradiado || false,
    sudoracion: triaje.sintomas?.sudoracion || false,
    nauseas: triaje.sintomas?.nauseas || false
  },
  diagnostico: {
    codigo_cie10: diagnosticos.codigo_cie10 || null,
    descripcion: diagnosticos.descripcion || null,
    severidad: diagnosticos.severidad || null
  },
  prediccion_ia: {
    riesgo_cv: predicciones.riesgo_cardiovascular?.valor_prediccion || null,
    confianza: predicciones.riesgo_cardiovascular?.confianza || null
  }
};

// Prompt específico para el AI Agent
const promptAIAgent = `Como cardiólogo experto, analiza este caso clínico y proporciona:

1. NIVEL DE RIESGO: CRÍTICO, ALTO, MODERADO, o BAJO
2. SCORE NUMÉRICO: 0-100
3. JUSTIFICACIÓN: Breve explicación médica

CASO CLÍNICO:
${JSON.stringify(contextoMedico, null, 2)}

Responde SOLO en este formato:
RIESGO: [NIVEL]
SCORE: [NÚMERO]
JUSTIFICACIÓN: [EXPLICACIÓN BREVE]`;

return {
  json: {
    paciente_id: pacienteId,
    atencion_id: entrada.atencion_id,
    campana_id: entrada.campana_id,
    contexto_medico: contextoMedico,
    prompt_ai_agent: promptAIAgent,
    datos_kmeans: {
      basicos: datosBasicos,
      clinicos: datosClinicos,
      triaje: triaje,
      diagnosticos: diagnosticos,
      predicciones: predicciones
    },
    timestamp: new Date().toISOString()
  }
};

// === GENERADOR DE SEGUIMIENTOS CORREGIDO ===
// MÁXIMO 3 SEGUIMIENTOS, MÁXIMO 45 DÍAS, SOLO CUESTIONARIOS

const datosPrevios = $('📋 Preparar para AI Agent').first().json;
const respuestaAIAgent = $input.first().json;
const datos = datosPrevios.datos_kmeans;

// Extraer evaluación del AI Agent
let evaluacionIA = 'MODERADO';
let scoreIA = 50;
let justificacion = 'Sin análisis';

try {
  const contenido = respuestaAIAgent.output || respuestaAIAgent.text || '';
  const lineas = contenido.split('\n');

  for (const linea of lineas) {
    if (linea.includes('RIESGO:')) {
      evaluacionIA = linea.replace('RIESGO:', '').trim();
    }
    if (linea.includes('SCORE:')) {
      scoreIA = parseInt(linea.replace('SCORE:', '').trim()) || 50;
    }
    if (linea.includes('JUSTIFICACIÓN:')) {
      justificacion = linea.replace('JUSTIFICACIÓN:', '').trim();
    }
  }
} catch (e) {
  console.log('Error parsing AI Agent response:', e.message);
}

// === CONFIGURACIÓN DE SEGUIMIENTOS SIMPLIFICADA ===
// SEGÚN TU ESPECIFICACIÓN: 1-3 seguimientos, máximo 45 días
const configuracionesSeguimiento = {
  'CRITICO_AGUDO': {
    seguimientos: [
      { dias_despues: 3, prioridad: 'ALTA' },
      { dias_despues: 7, prioridad: 'ALTA' },
      { dias_despues: 15, prioridad: 'MEDIA' }
    ],
    descripcion: '🚨 Seguimiento crítico - 3 cuestionarios urgentes'
  },
  'ALTO_RIESGO_ESTABLE': {
    seguimientos: [
      { dias_despues: 7, prioridad: 'ALTA' },
      { dias_despues: 20, prioridad: 'MEDIA' }
    ],
    descripcion: '🔴 Seguimiento alto riesgo - 2 cuestionarios'
  },
  'MODERADO_MULTIMORBIDO': {
    seguimientos: [
      { dias_despues: 7, prioridad: 'MEDIA' },
      { dias_despues: 20, prioridad: 'BAJA' }
    ],
    descripcion: '🟡 Seguimiento moderado - 2 cuestionarios (como tu ejemplo)'
  },
  'MODERADO_JOVEN': {
    seguimientos: [
      { dias_despues: 14, prioridad: 'MEDIA' },
      { dias_despues: 35, prioridad: 'BAJA' }
    ],
    descripcion: '🟠 Seguimiento preventivo joven - 2 cuestionarios'
  },
  'BAJO_PREVENTIVO': {
    seguimientos: [
      { dias_despues: 30, prioridad: 'BAJA' }
    ],
    descripcion: '🟢 Seguimiento preventivo - 1 cuestionario'
  }
};

// Determinar cluster K-means rápido
let clusterAsignado = 'MODERADO_JOVEN';
if (scoreIA >= 80) clusterAsignado = 'CRITICO_AGUDO';
else if (scoreIA >= 60) clusterAsignado = 'ALTO_RIESGO_ESTABLE';
else if (scoreIA >= 40) clusterAsignado = 'MODERADO_MULTIMORBIDO';
else if (scoreIA >= 20) clusterAsignado = 'MODERADO_JOVEN';
else clusterAsignado = 'BAJO_PREVENTIVO';

const configuracion = configuracionesSeguimiento[clusterAsignado];
const fechaBase = new Date();

// === GENERAR SEGUIMIENTOS (MÁXIMO 3, MÁXIMO 45 DÍAS) ===
const seguimientosGenerados = [];

configuacion.seguimientos.forEach((config, index) => {
  // Calcular fecha específica
  const fechaSeguimiento = new Date(fechaBase);
  fechaSeguimiento.setDate(fechaBase.getDate() + config.dias_despues);

  // Asegurar que no exceda 45 días
  const diasDiferencia = Math.floor((fechaSeguimiento - fechaBase) / (1000 * 60 * 60 * 24));
  if (diasDiferencia > 45) {
    fechaSeguimiento.setDate(fechaBase.getDate() + 45);
  }

  // Crear seguimiento
  const seguimiento = {
    seguimiento_numero: index + 1,
    paciente_id: datosPrevios.paciente_id,
    cluster_origen: clusterAsignado,
    fecha_programada: fechaSeguimiento.toISOString(),
    fecha_programada_display: fechaSeguimiento.toLocaleDateString('es-ES'),
    dias_despues_atencion: config.dias_despues,
    prioridad: config.prioridad,
    estado: 'PROGRAMADO',

    // SOLO CUESTIONARIOS CON CHATBOT (según tu especificación)
    tipo_interaccion: 'CUESTIONARIO_CHATBOT',
    descripcion: `Cuestionario cardiovascular ${index + 1} - ${config.prioridad}`,

    // Para tu compañero (generación de cuestionarios)
    contexto_cuestionario: {
      cluster_riesgo: clusterAsignado,
      score_riesgo: scoreIA,
      numero_seguimiento: index + 1,
      evaluacion_ai_agent: evaluacionIA,
      justificacion_medica: justificacion
    },

    // Metadatos del sistema
    generado_por: 'ai_agent_sistema',
    requiere_cuestionario_companero: true,
    timestamp_creacion: new Date().toISOString()
  };

  seguimientosGenerados.push(seguimiento);
});

console.log('=== SEGUIMIENTOS GENERADOS ===');
console.log('Paciente:', datosPrevios.paciente_id);
console.log('Cluster:', clusterAsignado);
console.log('AI Agent Score:', scoreIA);
console.log('Total seguimientos:', seguimientosGenerados.length);
console.log('Primer seguimiento:', seguimientosGenerados[0]?.fecha_programada_display);

// === RESULTADO FINAL ===
return {
  json: {
    paciente_id: datosPrevios.paciente_id,
    atencion_id: datosPrevios.atencion_id,
    campana_id: datosPrevios.campana_id,

    // ANÁLISIS AI AGENT + K-MEANS
    cluster_asignado: clusterAsignado,
    score_riesgo: scoreIA,
    evaluacion_ai_agent: {
      nivel: evaluacionIA,
      score: scoreIA,
      justificacion: justificacion
    },

    // SEGUIMIENTOS GENERADOS (CORREGIDOS)
    seguimientos_generados: seguimientosGenerados,
    total_seguimientos: seguimientosGenerados.length,

    // INFORMACIÓN PARA TU COMPAÑERO
    instrucciones_companero: {
      tipo_interaccion: 'CUESTIONARIO_CHATBOT',
      cluster_medico: clusterAsignado,
      score_ai_agent: scoreIA,
      total_cuestionarios_crear: seguimientosGenerados.length,
      enfoque: 'cardiovascular_personalizado',
      contextos: seguimientosGenerados.map(s => s.contexto_cuestionario)
    },

    // CONFIGURACIÓN APLICADA
    configuracion_aplicada: {
      cluster: clusterAsignado,
      descripcion: configuracion.descripcion,
      maximo_dias: 45,
      solo_cuestionarios: true
    },

    // FECHAS
    primer_seguimiento: seguimientosGenerados[0]?.fecha_programada_display,
    ultimo_seguimiento: seguimientosGenerados[seguimientosGenerados.length - 1]?.fecha_programada_display,

    timestamp_generacion: new Date().toISOString()
  }
};

